const generateUserProfileFromJson = (resumeJson)=>{
    if (!resumeJson) {
        return {
            name: "",
            avatar: "",
            location: "",
            level: "entry",
            title: "",
            experience: [],
            leadership: [],
            education: [],
            certifications: [],
            skills: []
        };
    }
    const levelMap = {
        'Intern': 'intern',
        'Entry Level': 'entry',
        'Mid Level': 'mid',
        'Senior Level': 'senior'
    };
    return {
        name: `${resumeJson.firstName} ${resumeJson.lastName}`,
        avatar: resumeJson.avatarUrl || "👨‍💻",
        location: resumeJson.location,
        level: levelMap[resumeJson.careerLevel] || 'entry',
        title: resumeJson.title,
        experience: resumeJson.experience.map((exp)=>({
                role: exp.role,
                company: exp.company,
                duration: `${exp.startDate} - ${exp.endDate}`,
                description: `${exp.role} at ${exp.company}`,
                achievements: exp.achievements
            })),
        leadership: [],
        education: resumeJson.education.map((edu)=>({
                degree: edu.degree,
                institution: edu.institution,
                year: edu.year,
                gpa: undefined,
                relevantCourses: undefined
            })),
        certifications: resumeJson.certifications.map((cert)=>({
                name: cert,
                issuer: "",
                year: "",
                credentialId: undefined,
                expiryDate: undefined
            })),
        skills: [
            {
                category: "Skills",
                items: resumeJson.skills,
                proficiency: 75
            }
        ]
    };
};
