// Helper function to generate daily challenges from resumeJson
const generateDailyChallengesFromJson = (resumeJson)=>{
    if (!resumeJson) return [];
    const challenges = [];
    const today = new Date();
    const deadline = new Date(today);
    deadline.setHours(23, 59, 59, 999);
    // Generate challenges based on skills
    if (resumeJson.skills.some((s)=>s.toLowerCase().includes('python'))) {
        challenges.push({
            id: "1",
            title: "Complete 2 Python Lessons",
            description: "Master advanced Python programming concepts",
            xpReward: 50,
            deadline: deadline.toISOString(),
            completed: false
        });
    }
    if (resumeJson.skills.some((s)=>s.toLowerCase().includes('machine learning') || s.toLowerCase().includes('ml'))) {
        challenges.push({
            id: "2",
            title: "Build an ML Model",
            description: "Create and tune a machine learning model",
            xpReward: 75,
            deadline: deadline.toISOString(),
            completed: false
        });
    }
    if (resumeJson.education.length > 0) {
        challenges.push({
            id: "3",
            title: "Update Academic Achievements",
            description: "Add your latest education credentials",
            xpReward: 30,
            deadline: deadline.toISOString(),
            completed: false
        });
    }
    return challenges.slice(0, 3);
};
