// Helper function to generate analytics from resumeJson
const generateAnalyticsFromJson = (resumeJson)=>{
    if (!resumeJson) {
        const emptyHistory = Array.from({
            length: 6
        }, (_, i)=>{
            const date = new Date();
            date.setDate(date.getDate() - (5 - i));
            return {
                date: date.toISOString().split('T')[0],
                views: 0,
                impressions: 0,
                appearances: 0
            };
        });
        return {
            profileViews: {
                total: 0,
                trend: 0,
                history: emptyHistory.map((d)=>({
                        date: d.date,
                        views: d.views
                    }))
            },
            postImpressions: {
                total: 0,
                trend: 0,
                history: emptyHistory.map((d)=>({
                        date: d.date,
                        impressions: d.impressions
                    }))
            },
            searchAppearances: {
                total: 0,
                trend: 0,
                history: emptyHistory.map((d)=>({
                        date: d.date,
                        appearances: d.appearances
                    }))
            }
        };
    }
    const stats = resumeJson.jobMatchStats;
    const history = Array.from({
        length: 6
    }, (_, i)=>{
        const date = new Date();
        date.setDate(date.getDate() - (5 - i));
        const baseViews = Math.floor(stats.profileViews / 6);
        const baseImpressions = Math.floor(stats.postImpressions / 6);
        const baseAppearances = Math.floor(stats.searchAppearances / 6);
        return {
            date: date.toISOString().split('T')[0],
            views: baseViews + Math.floor(Math.random() * 5),
            impressions: baseImpressions + Math.floor(Math.random() * 20),
            appearances: baseAppearances + Math.floor(Math.random() * 3)
        };
    });
    return {
        profileViews: {
            total: stats.profileViews,
            trend: 12.5,
            history: history.map((d)=>({
                    date: d.date,
                    views: d.views
                }))
        },
        postImpressions: {
            total: stats.postImpressions,
            trend: 8.3,
            history: history.map((d)=>({
                    date: d.date,
                    impressions: d.impressions
                }))
        },
        searchAppearances: {
            total: stats.searchAppearances,
            trend: 15.2,
            history: history.map((d)=>({
                    date: d.date,
                    appearances: d.appearances
                }))
        }
    };
};
