// Helper functions to generate data from resumeJson
const generateKpiFromJson = (resumeJson)=>{
    if (!resumeJson) return getDefaultKpi();
    // Calculate XP based on resume depth
    const baseXp = 100;
    const skillsXp = resumeJson.skills.length * 20;
    const experienceXp = resumeJson.experience.length * 50;
    const educationXp = resumeJson.education.length * 30;
    const certsXp = resumeJson.certifications.length * 25;
    const totalXp = baseXp + skillsXp + experienceXp + educationXp + certsXp;
    // Calculate level (every 200 XP = 1 level)
    const level = Math.floor(totalXp / 200) + 1;
    const nextLevelXp = level * 200;
    return {
        xp: totalXp,
        skills: resumeJson.skills.length,
        streak: 1,
        achievements: Math.floor(resumeJson.skills.length / 3) + Math.floor(resumeJson.experience.length / 2),
        mentorSessions: 0,
        jobViews: resumeJson.jobMatchStats.profileViews,
        level,
        nextLevelXp
    };
};
const generateSkillsFromJson = (resumeJson)=>{
    if (!resumeJson) return [];
    return resumeJson.skills.map((skill, i)=>({
            name: skill,
            value: Math.min(100, 60 + i * 10),
            lessons: "0/5",
            trend: "up",
            xp: 50 + i * 25
        }));
};
const generateAchievementsFromJson = (resumeJson)=>{
    if (!resumeJson) return [];
    const achievements = [];
    if (resumeJson.skills.length >= 5) {
        achievements.push({
            name: "🏅 Skill Master",
            description: "Mastered 5+ skills",
            xp: 50
        });
    }
    if (resumeJson.experience.length >= 3) {
        achievements.push({
            name: "🏅 Experienced Professional",
            description: "3+ years of experience",
            xp: 75
        });
    }
    if (resumeJson.certifications.length >= 2) {
        achievements.push({
            name: "🏅 Certified Expert",
            description: "Earned 2+ certifications",
            xp: 100
        });
    }
    return achievements;
};
